/**
 * Apple Music packs — the v1.0 catalogue.
 *
 * Each pack is a JSON file in `assets/curated-apple/`, generated by
 * `scripts/build-apple-packs.mjs` from the Deezer-era catalogue plus the Apple
 * Music mapping (`scripts/map-apple-music.mjs`). Unlike curated-Deezer packs
 * there is no runtime lookup at all: the Apple ID, duration and artwork are
 * baked in, and MusicKit fetches the audio at play time.
 *
 * Explicit handling happens at build time, not here. A song Apple rates
 * explicit is either swapped for its clean version or left out, so indices
 * stay dense and `totalTracks` is what actually plays.
 */
import { APPLE_PACK_LOADERS, APPLE_PACK_ORDER } from './apple-packs.generated';

export interface CuratedAppleTrack {
  appleId: string;
  title: string;
  artist: string;
  /** Movie / show / musical the track belongs to; '' when none. */
  source: string;
  durationMs: number;
  /** Apple artwork, already sized; '' when Apple has none. */
  artworkUrl: string;
}

export interface CuratedApplePlaylistData {
  id: string;
  name: string;
  tier: 'free' | 'locked';
  version: number;
  tracks: CuratedAppleTrack[];
}

const cache = new Map<string, CuratedApplePlaylistData>();

export function getCuratedApplePlaylist(id: string): CuratedApplePlaylistData {
  const cached = cache.get(id);
  if (cached) return cached;
  const loader = APPLE_PACK_LOADERS[id];
  if (!loader) throw new Error(`Unknown Apple Music pack: "${id}"`);
  const raw = loader() as CuratedApplePlaylistData;
  if (!raw || raw.id !== id) {
    throw new Error(`Apple Music pack file id "${raw?.id}" doesn't match registry key "${id}"`);
  }
  cache.set(id, raw);
  return raw;
}

export function getAllCuratedApplePlaylists(): CuratedApplePlaylistData[] {
  return APPLE_PACK_ORDER.map(getCuratedApplePlaylist);
}
